// Some portions generated by Claude
/**
 * Hub-and-satellite organization. A satellite is a node whose only link to the rest of the drawn graph is one
 * neighbour (its anchor), including the small chains hanging from it (a product and its label). Satellites are
 * peeled off, the remaining skeleton is laid out by the force layout with a halo reserved around every hub, and the
 * satellites are fanned back on the side of their anchor that faces away from its skeleton neighbours, grouped by
 * predicate and type. Hubs stay apart; their leaves show which cards belong to them.
 */
import {graphNodeSize} from './graph-geometry.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, GraphNode, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';

/** A hanging subtree larger than this is a community of its own and stays in the skeleton. */
export const SATELLITE_SUBTREE_LIMIT = 8;
/** Widest arc a fan may take around its anchor. */
const FAN_SPAN = Math.PI * 1.1;
const MIN_FAN_RADIUS = 110;
/** Side of the square the force layout keeps clear around a hub, relative to its fan radius. */
const HALO_SCALE = 1.5;
/** Satellites above this count go on staggered rings. */
const SINGLE_RING_LIMIT = 12;
/** Angular margin kept between a fan and the anchor's other neighbours. */
const FAN_MARGIN = 0.5;

export type PeeledGraph = {
  skeleton: Graph;
  /** satellite id → anchor id */
  anchorOf: Map<string, string>;
  /** anchor id → satellite ids */
  satellitesOf: Map<string, string[]>;
  /** skeleton node id → side of the square reserved for it in the force layout */
  halos: Map<string, number>;
};

type Adjacency = {index: Map<string, number>; neighbors: Set<number>[]};

function adjacency(graph: Graph): Adjacency {
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const neighbors = graph.nodes.map(() => new Set<number>());
  for (const edge of graph.edges) {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a === undefined || b === undefined || a === b) continue;
    neighbors[a].add(b);
    neighbors[b].add(a);
  }
  return {index, neighbors};
}

/** One node linked to every other node and nothing else: `computeNetworkLayout` draws it as a sunflower. */
export function isPureStar(graph: Graph) {
  if (graph.nodes.length < 20) return false;
  const {neighbors} = adjacency(graph);
  const hubs = neighbors.filter(set => set.size === graph.nodes.length - 1).length;
  return hubs === 1 && neighbors.every(set => set.size === 1 || set.size === graph.nodes.length - 1);
}

/** Spoke length a fan of these cards takes around its anchor when it may use the widest arc. */
export function fanRadius(anchor: GraphNode, satellites: readonly GraphNode[]) {
  const arc = satellites.reduce((sum, node) => sum + graphNodeSize(node).width + gap.nodeGapX, 0);
  return Math.max(MIN_FAN_RADIUS, graphNodeSize(anchor).height / 2 + 90, arc / FAN_SPAN);
}

/**
 * Splits a component into satellites and skeleton. Fixed nodes are never satellites. Nothing is peeled while a map is
 * being extended or repaired (`incremental`, `refine`, `repairOnly`), inside named groups, for coarse group graphs
 * (`nodeSizes`) or for a pure star, which has its own layout.
 */
export function peelSatellites(graph: Graph, options: LayoutOptions): PeeledGraph {
  const none = (): PeeledGraph => ({skeleton: graph, anchorOf: new Map(), satellitesOf: new Map(), halos: new Map()});
  if (options.incremental || options.refine || options.repairOnly || options.groups?.length || options.nodeSizes ||
      graph.nodes.length < 2 || isPureStar(graph)) return none();
  const {neighbors} = adjacency(graph);
  const n = graph.nodes.length;
  const fixed = graph.nodes.map(node => layoutNodeFixed(node, options));
  const anchor = new Int32Array(n).fill(-1);
  const subtree = new Int32Array(n).fill(1);
  let remaining = n, changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < n; i++) {
      if (anchor[i] !== -1 || fixed[i] || subtree[i] > SATELLITE_SUBTREE_LIMIT || remaining <= 1) continue;
      let free = -1, count = 0;
      for (const j of neighbors[i]) if (anchor[j] === -1) {free = j; count++;}
      if (count !== 1) continue;
      anchor[i] = free;
      subtree[free] += subtree[i];
      remaining--;
      changed = true;
    }
  }
  if (remaining === n) return none();
  const anchorOf = new Map<string, string>(), satellitesOf = new Map<string, string[]>();
  graph.nodes.forEach((node, i) => {
    if (anchor[i] === -1) return;
    const owner = graph.nodes[anchor[i]].id;
    anchorOf.set(node.id, owner);
    const list = satellitesOf.get(owner);
    if (list) list.push(node.id);
    else satellitesOf.set(owner, [node.id]);
  });
  const skeletonNodes = graph.nodes.filter((_, i) => anchor[i] === -1);
  const skeletonIds = new Set(skeletonNodes.map(node => node.id));
  const skeleton: Graph = {...graph, nodes: skeletonNodes,
    edges: graph.edges.filter(edge => skeletonIds.has(edge.source) && skeletonIds.has(edge.target))};
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const halos = new Map<string, number>();
  for (const node of skeletonNodes) {
    const satellites = satellitesOf.get(node.id);
    if (satellites?.length) halos.set(node.id, fanRadius(node, satellites.map(id => byId.get(id)!)) * HALO_SCALE);
  }
  return {skeleton, anchorOf, satellitesOf, halos};
}

/** Neighbours considered per node when looking for shared neighbours; bounds the work on hubs. */
const SIMILARITY_NEIGHBOR_LIMIT = 48;
const SIMILARITY_IDEAL_LENGTH = 40;
const SIMILARITY_ELASTICITY = 0.1;

export type LayoutSpring = {source: string; target: string; ideal: number; elasticity: number};

/**
 * Force-layout springs between skeleton nodes of the same first type that share at least one neighbour: nodes that
 * play the same role end up side by side. They are never statements, never drawn, scored or routed.
 */
export function similaritySprings(graph: Graph, peeled: PeeledGraph): LayoutSpring[] {
  const skeleton = peeled.skeleton;
  const {neighbors} = adjacency(skeleton);
  const typeOf = skeleton.nodes.map(node => node.types?.[0]?.id ?? '');
  const shared = new Map<string, number>();
  skeleton.nodes.forEach((node, v) => {
    if (!typeOf[v]) return;
    let seen = 0;
    for (const w of neighbors[v]) {
      if (seen++ >= SIMILARITY_NEIGHBOR_LIMIT) break;
      let inner = 0;
      for (const u of neighbors[w]) {
        if (inner++ >= SIMILARITY_NEIGHBOR_LIMIT) break;
        if (u <= v || typeOf[u] !== typeOf[v]) continue;
        const key = `${v}:${u}`;
        shared.set(key, (shared.get(key) ?? 0) + 1);
      }
    }
  });
  return [...shared]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, count]) => {
      const [v, u] = key.split(':').map(Number);
      return {source: skeleton.nodes[v].id, target: skeleton.nodes[u].id, ideal: SIMILARITY_IDEAL_LENGTH, elasticity: SIMILARITY_ELASTICITY * count};
    });
}

type Segment = [PointerPosition, PointerPosition];

function segmentsCross(a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition) {
  const ccw = (p: PointerPosition, q: PointerPosition, r: PointerPosition) => (r.y - p.y) * (q.x - p.x) > (q.y - p.y) * (r.x - p.x);
  return ccw(a, c, d) !== ccw(b, c, d) && ccw(a, b, c) !== ccw(a, b, d);
}

/**
 * Places every satellite around its anchor, into the widest angle between the anchor's placed neighbours, ordered by
 * the predicate that links them to the anchor, then their first type, with literals last. The fan's centre is shifted
 * within that angle when it would cross placed spokes or land on placed cards. Anchors with more satellites go first;
 * a satellite that has satellites of its own fans them outward. Fixed satellites keep their coordinates.
 */
export function placeSatellites(graph: Graph, positions: Map<string, PointerPosition>, peeled: PeeledGraph, options: LayoutOptions) {
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const {index, neighbors} = adjacency(graph);
  const predicateTo = new Map<string, string>();
  for (const edge of graph.edges.slice().sort((a, b) => a.id.localeCompare(b.id))) {
    for (const [self, other] of [[edge.source, edge.target], [edge.target, edge.source]]) {
      if (peeled.anchorOf.get(self) === other && !predicateTo.has(self)) predicateTo.set(self, edge.predicate);
    }
  }
  const sortKey = (id: string) => {
    const node = byId.get(id)!;
    return `${predicateTo.get(id) ?? ''}\u0000${node.types?.[0]?.id ?? '\uffff'}\u0000${node.kind === 'literal' ? 1 : 0}\u0000${node.label}\u0000${id}`;
  };
  const placed: Segment[] = [];
  for (const edge of peeled.skeleton.edges) {
    const a = positions.get(edge.source), b = positions.get(edge.target);
    if (a && b && edge.source !== edge.target) placed.push([a, b]);
  }
  const cardNear = (p: PointerPosition, exclude: Set<string>) => {
    let penalty = 0;
    for (const [id, q] of positions) {
      if (exclude.has(id)) continue;
      const size = graphNodeSize(byId.get(id)!);
      if (Math.abs(q.x - p.x) < size.width / 2 + 80 && Math.abs(q.y - p.y) < size.height / 2 + 60) penalty += 0.7;
    }
    return penalty;
  };

  const place = (anchorId: string) => {
    const kids = (peeled.satellitesOf.get(anchorId) ?? []).slice().sort((a, b) => sortKey(a).localeCompare(sortKey(b)));
    const center = positions.get(anchorId);
    if (!center || !kids.length) return;
    const movable = kids.filter(id => !layoutNodeFixed(byId.get(id)!, options));
    const kidSet = new Set(kids);
    const occupied = [...neighbors[index.get(anchorId)!]]
      .map(i => graph.nodes[i].id)
      .filter(id => !kidSet.has(id) || (positions.has(id) && !movable.includes(id)))
      .flatMap(id => {const p = positions.get(id); return p ? [Math.atan2(p.y - center.y, p.x - center.x)] : [];})
      .sort((a, b) => a - b);
    if (movable.length) {
      let gapStart = 0, gapSize = Math.PI * 2;
      if (occupied.length) {
        gapSize = 0;
        occupied.forEach((a, i) => {
          const next = i + 1 < occupied.length ? occupied[i + 1] : occupied[0] + Math.PI * 2;
          if (next - a > gapSize) {gapSize = next - a; gapStart = a;}
        });
      }
      const fullCircle = !occupied.length;
      const cards = movable.map(id => byId.get(id)!), sizes = cards.map(graphNodeSize);
      const anchorSize = graphNodeSize(byId.get(anchorId)!);
      const arc = sizes.reduce((sum, size) => sum + size.width + gap.nodeGapX, 0);
      const available = fullCircle ? Math.PI * 2 : Math.max(0.3, Math.min(FAN_SPAN, gapSize - FAN_MARGIN * 2));
      const rings = Math.max(1, Math.ceil(Math.sqrt(movable.length / SINGLE_RING_LIMIT)));
      const stride = Math.max(...sizes.map(size => Math.hypot(size.width + gap.nodeGapX, size.height + gap.nodeGapY)));
      const radius = Math.max(MIN_FAN_RADIUS, anchorSize.height / 2 + 90, arc / rings / available);
      const span = fullCircle ? Math.PI * 2 : Math.min(available, arc / rings / radius);
      const bisector = fullCircle ? 0 : gapStart + gapSize / 2;
      const proposal = (centerAngle: number) => {
        const result: PointerPosition[] = [];
        let offset = 0;
        for (let ring = 0; ring < rings; ring++) {
          const count = Math.ceil((movable.length - offset) / (rings - ring));
          const r = radius + ring * stride;
          for (let k = 0; k < count; k++) {
            const angle = fullCircle
              ? centerAngle + ((k + (ring % 2) * .5) / count) * Math.PI * 2
              : movable.length === 1 ? centerAngle : centerAngle - span / 2 + ((k + .5 + (ring % 2) * .25) / count) * span;
            result.push({x: center.x + Math.cos(angle) * r, y: center.y + Math.sin(angle) * r});
          }
          offset += count;
        }
        return result;
      };
      let bestCost = Number.POSITIVE_INFINITY, bestPoints: PointerPosition[] = [];
      const limit = fullCircle ? 0 : Math.max(0, (gapSize - span) / 2 - FAN_MARGIN);
      const step = Math.max(0.05, limit / 6);
      const offsets = [0];
      for (let d = step; d <= limit + 1e-9; d += step) offsets.push(-d, d);
      const exclude = new Set([anchorId, ...kids]);
      for (const d of offsets) {
        const points = proposal(bisector + d);
        let cost = Math.abs(d) * 0.1;
        for (const p of points) {
          for (const [a, b] of placed) if (a !== center && b !== center && segmentsCross(center, p, a, b)) cost += 1;
          cost += cardNear(p, exclude);
        }
        if (cost < bestCost) {bestCost = cost; bestPoints = points;}
      }
      movable.forEach((id, i) => {
        positions.set(id, bestPoints[i]);
        placed.push([center, bestPoints[i]]);
      });
    }
    kids.forEach(id => {
      if (!positions.has(id)) positions.set(id, {x: center.x, y: center.y});
      place(id);
    });
  };
  const anchors = [...peeled.satellitesOf.keys()]
    .filter(id => !peeled.anchorOf.has(id))
    .sort((a, b) => (peeled.satellitesOf.get(b)?.length ?? 0) - (peeled.satellitesOf.get(a)?.length ?? 0) || a.localeCompare(b));
  anchors.forEach(place);
  for (const node of graph.nodes) {
    if (positions.has(node.id)) continue;
    const owner = peeled.anchorOf.get(node.id);
    positions.set(node.id, (owner ? positions.get(owner) : undefined) ?? {x: node.x ?? 0, y: node.y ?? 0});
  }
}
